@testable import EversenseKit
import Testing

struct PackageTest {
    @Test func glucoseTest() async throws {
        let data =
            Data(
                hex: ""
            )

        Eversense365.sensorIdLength = 0x0A
        let glucoseData = Eversense365.GetGlucoseDataPacket()
        let result = glucoseData.parseResponse(data: data)

        #expect(result.glucoseInMgDl != 0xFFFF)
    }

    @Test func signalStrength() async throws {
        let data = Data(hex: "421B010A000000000000000000009C622EB80000000074083B73034003")

        Eversense365.sensorIdLength = 0x0A
        let signalStrength = Eversense365.GetSignalStrenghtPacket()
        let result = signalStrength.parseResponse(data: data)

        #expect(result.signalStrength != SignalStrength.NoSignal)
    }

    @Test func calibrationData() async throws {
        let data = Data(hex: "421d03005eb38e50c30000000104000000000000ac4bb32bc30000006d0118009b265db3a42bc3000000")

        Eversense365.sensorIdLength = 0x0A
        let calibrationData = Eversense365.GetCalibrationInfoPacket()
        let result = calibrationData.parseResponse(data: data)

        #expect(result.currentPhase != .DEBUG)
    }

    @Test func sensorInformation() async throws {
        let data =
            Data(
                hex: ""
            )
//            Data(
//                hex: ""
//            )

        let sensorInformation = Eversense365.GetSensorInformationPacket()
        let result = sensorInformation.parseResponse(data: data)

        #expect(result.communicationProtocolVersion >= 1.06)
        #expect(result.sensorIdLength == 0x0A)
    }

    @Test func glucoseLog() async throws {
        let data =
            Data(
                hex: ""
            )

        Eversense365.sensorIdLength = 0x0A
        let packet = Eversense365.GetGlucoseLogValuesPacket(from: 38166, to: 38217)
        let result = packet.parseResponse(data: data)

        #expect(!result.glucoseHistory.isEmpty)
    }

    @Test func activeAlarms() async throws {
        let data = Data(hex: "42220139002c")

        Eversense365.sensorIdLength = 0x0A
        let packet = Eversense365.GetActiveAlarmsPacket()
        let result = packet.parseResponse(data: data)

        #expect(result.count == 1)
    }
}
